   200→<body>
   201→    <header>
   202→        <div class="container">
   203→            <h1>KIDNAP BLACKMAIL/EXTORTION</h1>
   204→            <h2 style="text-align: center; color: white;">Call Handler's Actions Checklist</h2>
   205→        </div>
   206→    </header>
   207→    
   208→    <main class="container">
   209→        <div class="section">
   210→            <div class="section-header">
   211→                Please Provide The Caller With The Following, once complete use the Email to FIM/FCIM button.
   212→            </div>
   213→            <div class="section-body">
   214→                <div class="checklist-item">
   215→                    <div class="instruction">
   216→                        A specialist officer will recall using the code word. If no code word is provided then no information should be given.
   217→                    </div>
   218→                    <select class="status-select" id="item1">
   219→                        <option value="">Select status</option>
   220→                        <option value="DONE">DONE</option>
   221→                        <option value="PENDING">PENDING</option>
   222→                        <option value="N/A">N/A</option>
   223→                    </select>
   224→                </div>
   225→                
   226→                <div class="checklist-item">
   227→                    <div class="instruction">
   228→                        Tell them to come up with a credible cover story if they are questioned as to why their phone is engaged (ie speaking to the bank or a friend etc).
   229→                    </div>
   230→                    <select class="status-select" id="item2">
   231→                        <option value="">Select status</option>
   232→                        <option value="DONE">DONE</option>
   233→                        <option value="PENDING">PENDING</option>
   234→                        <option value="N/A">N/A</option>
   235→                    </select>
   236→                </div>
   237→                
   238→                <div class="checklist-item">
   239→                    <div class="instruction">
   240→                        Explain to the caller they MUST maintain secrecy even to family and friends.
   241→                    </div>
   242→                    <select class="status-select" id="item3">
   243→                        <option value="">Select status</option>
   244→                        <option value="DONE">DONE</option>
   245→                        <option value="PENDING">PENDING</option>
   246→                        <option value="N/A">N/A</option>
   247→                    </select>
   248→                </div>
   249→                
   250→                <div class="checklist-item">
   251→                    <div class="instruction">
   252→                        Keep a record of any calls received (times, dates, tel numbers).
   253→                    </div>
   254→                    <select class="status-select" id="item4">
   255→                        <option value="">Select status</option>
   256→                        <option value="DONE">DONE</option>
   257→                        <option value="PENDING">PENDING</option>
   258→                        <option value="N/A">N/A</option>
   259→                    </select>
   260→                </div>
   261→                
   262→                <div class="checklist-item">
   263→                    <div class="instruction">
   264→                        Complete a 1471 enquiry after any calls if they have no identification facility on their phone.
   265→                    </div>
   266→                    <select class="status-select" id="item5">
   267→                        <option value="">Select status</option>
   268→                        <option value="DONE">DONE</option>
   269→                        <option value="PENDING">PENDING</option>
   270→                        <option value="N/A">N/A</option>
   271→                    </select>
   272→                </div>
   273→                
   274→                <div class="checklist-item">
   275→                    <div class="instruction">
   276→                        Keep the phone line free for any further contact from the offenders/police.
   277→                    </div>
   278→                    <select class="status-select" id="item6">
   279→                        <option value="">Select status</option>
   280→                        <option value="DONE">DONE</option>
   281→                        <option value="PENDING">PENDING</option>
   282→                        <option value="N/A">N/A</option>
   283→                    </select>
   284→                </div>
   285→                
   286→                <div class="checklist-item">
   287→                    <div class="instruction">
   288→                        Do not attempt to record any conversations as this may alert the offenders.
   289→                    </div>
   290→                    <select class="status-select" id="item7">
   291→                        <option value="">Select status</option>
   292→                        <option value="DONE">DONE</option>
   293→                        <option value="PENDING">PENDING</option>
   294→                        <option value="N/A">N/A</option>
   295→                    </select>
   296→                </div>
   297→                
   298→                <div class="checklist-item">
   299→                    <div class="instruction">
   300→                        Advice the caller that any direct approach to them by the Police will be by plain clothes officers who will produce ID. This may cause a delay in our response.
   301→                    </div>
   302→                    <select class="status-select" id="item8">
   303→                        <option value="">Select status</option>
   304→                        <option value="DONE">DONE</option>
   305→                        <option value="PENDING">PENDING</option>
   306→                        <option value="N/A">N/A</option>
   307→                    </select>
   308→                </div>
   309→                
   310→                <div class="checklist-item">
   311→                    <div class="instruction">
   312→                        If not already given, provide the caller with a secure contact number 0161 856 1884 to enable them to provide any further information should they be made aware of any, if there is no answer, please advise the caller to ring on 999.
   313→                    </div>
   314→                    <select class="status-select" id="item9">
   315→                        <option value="">Select status</option>
   316→                        <option value="DONE">DONE</option>
   317→                        <option value="PENDING">PENDING</option>
   318→                        <option value="N/A">N/A</option>
   319→                    </select>
   320→                </div>
   321→            </div>
   322→        </div>
   323→        
   324→        <div class="actions">
   325→            <button id="copy-email-btn" class="btn btn-primary">Email to FDO/FCIM</button>
   326→            <button id="reset-btn" class="btn btn-danger">Reset Form</button>
   327→            
   328→            <a href="cia.html" class="btn btn-home">RETURN TO START</a>
   329→        </div>
   330→        
   331→        <textarea id="hidden-copy-area" class="hidden"></textarea>
   332→        <div id="success-message">Checklist copied and email opened!</div>
   333→    </main>
   334→    
   335→    <footer>
   336→        <div class="container">
   337→            <p>&copy; 2025 Greater Manchester Police - Confidential Internal System</p>
   338→        </div>
   339→    </footer>
   340→    
   341→    <script>
   342→        document.addEventListener('DOMContentLoaded', function() {
   343→            const copyEmailBtn = document.getElementById('copy-email-btn');
   344→            const resetBtn = document.getElementById('reset-btn');
   345→            const hiddenCopyArea = document.getElementById('hidden-copy-area');
   346→            const successMessage = document.getElementById('success-message');
   347→            
   348→            // Load previously saved values if they exist
   349→            for(let i = 1; i <= 9; i++) {
   350→                const item = document.getElementById('item' + i);
   351→                if(sessionStorage.getItem('action_item' + i)) {
   352→                    item.value = sessionStorage.getItem('action_item' + i);
   353→                }
   354→                
   355→                // Save values to session storage on change
   356→                item.addEventListener('change', function() {
   357→                    sessionStorage.setItem('action_item' + i, this.value);
   358→                });
   359→            }
   360→            
   361→            copyEmailBtn.addEventListener('click', function() {
   362→                // Gather all checklist data
   363→                let checklistData = '';
   364→                checklistData += '-------KIDNAP BLACKMAIL/EXTORTION - CALL HANDLER ACTIONS CHECKLIST-------\n\n';
   365→                
   366→                // Get each item and its status
   367→                const items = [
   368→                    'A specialist officer will recall using the code word. If no code word is provided then no information should be given.',
   369→                    'Tell them to come up with a credible cover story if they are questioned as to why their phone is engaged (ie speaking to the bank or a friend etc).',
   370→                    'Explain to the caller they MUST maintain secrecy even to family and friends.',
   371→                    'Keep a record of any calls received (times, dates, tel numbers).',
   372→                    'Complete a 1471 enquiry after any calls if they have no identification facility on their phone.',
   373→                    'Keep the phone line free for any further contact from the offenders/police.',
   374→                    'Do not attempt to record any conversations as this may alert the offenders.',
   375→                    'Advice the caller that any direct approach to them by the Police will be by plain clothes officers who will produce ID. This may cause a delay in our response.',
   376→                    'If not already given, provide the caller with a secure contact number 0161 856 1884 to enable them to provide any further information should they be made aware of any.'
   377→                ];
   378→                
   379→                for(let i = 0; i < items.length; i++) {
   380→                    const status = document.getElementById('item' + (i + 1)).value || 'Not Completed';
   381→                    checklistData += (i + 1) + '. ' + items[i] + '\n';
   382→                    checklistData += '   Status: ' + status + '\n\n';
   383→                }
   384→                
   385→                // Copy to clipboard
   386→                hiddenCopyArea.value = checklistData;
   387→                hiddenCopyArea.select();
   388→                document.execCommand('copy');
   389→                
   390→                // Show success message
   391→                successMessage.style.display = 'block';
   392→                setTimeout(function() {
   393→                    successMessage.style.display = 'none';
   394→                }, 3000);
   395→                
   396→                // Open email client with pre-populated data
   397→                const emailSubject = encodeURIComponent('Call Handlers Actions Checklist');
   398→                const emailBody = encodeURIComponent(checklistData);
   399→                window.location.href = `mailto:fim@gmp.police.uk, fcim@gmp.police.uk?subject=${emailSubject}&body=${emailBody}`;
   400→            });
   401→            
   402→            resetBtn.addEventListener('click', function() {
   403→                // Reset all select elements
   404→                for(let i = 1; i <= 9; i++) {
   405→                    document.getElementById('item' + i).value = '';
   406→                    sessionStorage.removeItem('action_item' + i);
   407→                }
   408→            });
   409→        });
   410→    </script>
   411→</body>
   412→</html>

